subconscious/glm-5.2.swiftSnippet:
import LingXiAgent

// 1. One-line inference via LingXiAgent Registry
let model = LingXiAgent.model("subconscious/subconscious/glm-5.2", apiKey: processEnvironment["SUBCONSCIOUS_API_KEY"])

// 2. Or initialize via OpenAI-Compatible factory
let provider = LingXiProvider.openAICompatible(
    baseURL: URL(string: "https://api.subconscious.dev/v1")!,
    apiKey: processEnvironment["SUBCONSCIOUS_API_KEY"]
)
let session = provider.model("subconscious/glm-5.2")

// 3. Stream responses with reasoning support
for try await chunk in session.stream("Hello, LingXi!") {
    if let reasoning = chunk.reasoning {
        print("[Thinking] \(reasoning)", terminator: "")
    }
    print(chunk.text, terminator: "")
}

