let model = LingXiAgent.model("snowflake-cortex/gemini-3.1-pro", apiKey: processEnvironment["SNOWFLAKE_ACCOUNT"])

// 2. Or initialize via OpenAI-Compatible factory
let provider = LingXiProvider.openAICompatible(
    baseURL: URL(string: "https://${SNOWFLAKE_ACCOUNT}.snowflakecomputing.com/api/v2/cortex/v1")!,
    apiKey: processEnvironment["SNOWFLAKE_ACCOUNT"]
)
let session = provider.model("gemini-3.1-pro")

// 3. Stream responses with reasoning support
for try await chunk in session.stream("Hello, LingXi!") {
